import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import YouTube from 'react-youtube';
import './Room.css';

// Real WebSocket Service (will connect to your Java backend)
class RealWebSocket {
  constructor(roomId, userId, username, callbacks) {
    this.roomId = roomId;
    this.userId = userId;
    this.username = username;
    this.callbacks = callbacks;
    this.socket = null;
    
    // Connect to WebSocket (will connect to your Java backend)
    const wsUrl = process.env.REACT_APP_WS_URL || 'ws://localhost:8080/ws';
    this.socket = new WebSocket(`${wsUrl}?roomId=${roomId}&userId=${userId}&username=${username}`);
    
    this.socket.onopen = () => {
      console.log('WebSocket connected');
      callbacks.onConnect && callbacks.onConnect();
    };
    
    this.socket.onmessage = (event) => {
      const data = JSON.parse(event.data);
      const { type, payload } = data;
      
      switch(type) {
        case 'play':
          callbacks.onPlay && callbacks.onPlay(payload);
          break;
        case 'pause':
          callbacks.onPause && callbacks.onPause(payload);
          break;
        case 'seek':
          callbacks.onSeek && callbacks.onSeek(payload);
          break;
        case 'change_video':
          callbacks.onVideoChange && callbacks.onVideoChange(payload);
          break;
        case 'user_joined':
          callbacks.onUserJoined && callbacks.onUserJoined(payload);
          break;
        case 'user_left':
          callbacks.onUserLeft && callbacks.onUserLeft(payload);
          break;
        case 'role_assigned':
          callbacks.onRoleAssigned && callbacks.onRoleAssigned(payload);
          break;
        case 'participant_removed':
          callbacks.onParticipantRemoved && callbacks.onParticipantRemoved(payload);
          break;
        case 'chat':
          callbacks.onChat && callbacks.onChat(payload);
          break;
        default:
          break;
      }
    };
    
    this.socket.onerror = (error) => {
      console.error('WebSocket error:', error);
      callbacks.onError && callbacks.onError('Connection error');
    };
  }
  
  send(type, data) {
    if (this.socket && this.socket.readyState === WebSocket.OPEN) {
      this.socket.send(JSON.stringify({ type, data }));
    }
  }
  
  sendPlay(roomId, userId) {
    this.send('play', { roomId, userId });
  }
  
  sendPause(roomId, userId) {
    this.send('pause', { roomId, userId });
  }
  
  sendSeek(roomId, userId, time) {
    this.send('seek', { roomId, userId, time });
  }
  
  sendChangeVideo(roomId, userId, videoId) {
    this.send('change_video', { roomId, userId, videoId });
  }
  
  sendAssignRole(roomId, userId, targetId, role) {
    this.send('assign_role', { roomId, userId, targetId, role });
  }
  
  sendRemoveParticipant(roomId, userId, targetId) {
    this.send('remove_participant', { roomId, userId, targetId });
  }
  
  sendChat(roomId, userId, username, message) {
    this.send('chat', { roomId, userId, username, message });
  }
  
  disconnect() {
    if (this.socket) {
      this.send('leave_room', { roomId: this.roomId, userId: this.userId });
      this.socket.close();
    }
  }
}

const Room = () => {
  const { roomId } = useParams();
  const navigate = useNavigate();
  const [participants, setParticipants] = useState([]);
  const [player, setPlayer] = useState(null);
  const [userRole, setUserRole] = useState('PARTICIPANT');
  const [currentVideoId, setCurrentVideoId] = useState('dQw4w9WgXcQ');
  const [newVideoUrl, setNewVideoUrl] = useState('');
  const [chatMessages, setChatMessages] = useState([]);
  const [chatInput, setChatInput] = useState('');
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(100);
  const [isSeeking, setIsSeeking] = useState(false);
  
  const userId = localStorage.getItem('userId');
  const username = localStorage.getItem('username');
  const wsService = useRef(null);

  useEffect(() => {
    if (!userId || !username) {
      navigate('/');
      return;
    }

    // Get role from localStorage (set when creating/joining room)
    const role = localStorage.getItem('role') || 'PARTICIPANT';
    setUserRole(role);
    
    // Initialize with current user only (no mock participants)
    setParticipants([
      {
        userId: userId,
        username: username,
        role: role
      }
    ]);

    // Connect to real WebSocket
    wsService.current = new RealWebSocket(roomId, userId, username, {
      onConnect: () => {
        console.log('Connected to room:', roomId);
      },
      onPlay: () => {
        if (player && player.getPlayerState() !== 1) {
          player.playVideo();
        }
      },
      onPause: () => {
        if (player && player.getPlayerState() === 1) {
          player.pauseVideo();
        }
      },
      onSeek: (data) => {
        if (player) {
          player.seekTo(data.time, true);
          setCurrentTime(data.time);
        }
      },
      onVideoChange: (data) => {
        setCurrentVideoId(data.videoId);
        setCurrentTime(0);
        if (player) {
          player.loadVideoById(data.videoId);
        }
      },
      onUserJoined: (data) => {
        setParticipants(prev => [...prev, data]);
        addChatMessage('system', `✨ ${data.username} joined the party!`);
      },
      onUserLeft: (data) => {
        setParticipants(prev => prev.filter(p => p.userId !== data.userId));
        addChatMessage('system', `👋 ${data.username} left the party!`);
      },
      onRoleAssigned: (data) => {
        setParticipants(prev => 
          prev.map(p => p.userId === data.userId ? {...p, role: data.role} : p)
        );
        if (data.userId === userId) {
          setUserRole(data.role);
          addChatMessage('system', `👑 You are now a ${data.role}!`);
        } else {
          const user = participants.find(p => p.userId === data.userId);
          if (user) {
            addChatMessage('system', `👑 ${user.username} is now a ${data.role}!`);
          }
        }
      },
      onParticipantRemoved: (data) => {
        if (data.userId === userId) {
          alert('You have been removed from the room by the host!');
          navigate('/');
        } else {
          setParticipants(prev => prev.filter(p => p.userId !== data.userId));
          addChatMessage('system', `🚫 A participant was removed`);
        }
      },
      onChat: (data) => {
        addChatMessage(data.username, data.message);
      },
      onError: (error) => {
        console.error('WebSocket error:', error);
      }
    });

    // Update current time periodically
    const interval = setInterval(() => {
      if (player && !isSeeking) {
        const time = player.getCurrentTime();
        if (time) setCurrentTime(time);
        const dur = player.getDuration();
        if (dur) setDuration(dur);
      }
    }, 1000);

    return () => {
      clearInterval(interval);
      if (wsService.current) {
        wsService.current.disconnect();
      }
    };
  }, [roomId, userId, username, navigate, player, isSeeking]);

  const formatTime = (seconds) => {
    if (!seconds || isNaN(seconds)) return '0:00';
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const addChatMessage = (sender, message) => {
    setChatMessages(prev => [...prev, { sender, message, timestamp: new Date() }]);
    setTimeout(() => {
      const container = document.querySelector('.chat-messages');
      if (container) container.scrollTop = container.scrollHeight;
    }, 100);
  };

  const onPlayerReady = (event) => {
    setPlayer(event.target);
    setDuration(event.target.getDuration());
  };

  const onPlayerStateChange = (event) => {
    if (!isSeeking && (userRole === 'HOST' || userRole === 'MODERATOR')) {
      if (event.data === 1) {
        wsService.current.sendPlay(roomId, userId);
      } else if (event.data === 2) {
        wsService.current.sendPause(roomId, userId);
      }
    }
  };

  const handleSeekStart = () => {
    setIsSeeking(true);
  };

  const handleSeekChange = (e) => {
    const time = parseFloat(e.target.value);
    setCurrentTime(time);
  };

  const handleSeekEnd = (e) => {
    const time = parseFloat(e.target.value);
    setIsSeeking(false);
    if (player && (userRole === 'HOST' || userRole === 'MODERATOR')) {
      player.seekTo(time, true);
      wsService.current.sendSeek(roomId, userId, time);
    }
  };

  const extractVideoId = (url) => {
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
    const match = url.match(regExp);
    return (match && match[2].length === 11) ? match[2] : null;
  };

  const handleChangeVideo = () => {
    const videoId = extractVideoId(newVideoUrl);
    if (videoId) {
      wsService.current.sendChangeVideo(roomId, userId, videoId);
      setNewVideoUrl('');
    } else {
      alert('Invalid YouTube URL. Please paste a valid YouTube link!');
    }
  };

  const assignRole = (targetId, role) => {
    wsService.current.sendAssignRole(roomId, userId, targetId, role);
  };

  const removeParticipant = (targetId) => {
    if (window.confirm('Are you sure you want to remove this participant?')) {
      wsService.current.sendRemoveParticipant(roomId, userId, targetId);
    }
  };

  const sendChat = () => {
    if (chatInput.trim()) {
      wsService.current.sendChat(roomId, userId, username, chatInput);
      setChatInput('');
    }
  };

  const copyRoomCode = () => {
    navigator.clipboard.writeText(roomId);
    alert('Room code copied!');
  };

  const opts = {
    height: '450',
    width: '100%',
    playerVars: {
      autoplay: 0,
      controls: 1,
      modestbranding: 1,
      rel: 0,
      showinfo: 0,
    },
  };

  const canControl = userRole === 'HOST' || userRole === 'MODERATOR';

  return (
    <div className="room-container">
      <div className="room-header">
        <h2>
          🎬 YouTube Watch Party
          <span className="room-code" onClick={copyRoomCode} style={{ cursor: 'pointer' }}>
            📋 {roomId}
          </span>
        </h2>
        <div>
          <span style={{ marginRight: '15px', fontWeight: 'bold' }}>
            {userRole === 'HOST' ? '👑 HOST' : userRole === 'MODERATOR' ? '⭐ MODERATOR' : '👤 PARTICIPANT'}
          </span>
          <button className="btn btn-danger" onClick={() => navigate('/')}>
            🚪 Leave Room
          </button>
        </div>
      </div>

      <div className="room-content">
        <div className="video-section">
          <YouTube
            videoId={currentVideoId}
            opts={opts}
            onReady={onPlayerReady}
            onStateChange={onPlayerStateChange}
          />
          
          <div className="seek-bar-container">
            <div className="time-display">
              <span>{formatTime(currentTime)}</span>
              <span>/</span>
              <span>{formatTime(duration)}</span>
            </div>
            <input
              type="range"
              min="0"
              max={duration || 100}
              step="0.1"
              value={currentTime}
              onMouseDown={handleSeekStart}
              onChange={handleSeekChange}
              onMouseUp={handleSeekEnd}
              onTouchStart={handleSeekStart}
              onTouchEnd={handleSeekEnd}
              disabled={!player || !canControl}
              className="seek-bar"
            />
          </div>
          
          {canControl && (
            <div className="controls">
              <button onClick={() => player?.playVideo()} className="control-btn">
                ▶ Play
              </button>
              <button onClick={() => player?.pauseVideo()} className="control-btn">
                ⏸ Pause
              </button>
              <div className="video-change">
                <input
                  type="text"
                  placeholder="🔗 Paste YouTube URL here..."
                  value={newVideoUrl}
                  onChange={(e) => setNewVideoUrl(e.target.value)}
                  onKeyPress={(e) => e.key === 'Enter' && handleChangeVideo()}
                />
                <button onClick={handleChangeVideo} className="control-btn">
                  🎬 Change Video
                </button>
              </div>
            </div>
          )}
        </div>

        <div className="sidebar">
          <div className="participants-section">
            <h3>👥 Participants ({participants.length})</h3>
            <ul>
              {participants.map((p) => (
                <li key={p.userId} className="participant-item">
                  <span className="participant-name">
                    {p.username}
                    {p.userId === userId && ' (You)'}
                  </span>
                  <span className={`role-badge role-${p.role.toLowerCase()}`}>
                    {p.role === 'HOST' && '👑 '}
                    {p.role === 'MODERATOR' && '⭐ '}
                    {p.role === 'PARTICIPANT' && '👤 '}
                    {p.role}
                  </span>
                  {userRole === 'HOST' && p.userId !== userId && (
                    <div className="participant-actions">
                      {p.role !== 'MODERATOR' && (
                        <button onClick={() => assignRole(p.userId, 'MODERATOR')}>
                          ⭐ Make Moderator
                        </button>
                      )}
                      {p.role !== 'PARTICIPANT' && (
                        <button onClick={() => assignRole(p.userId, 'PARTICIPANT')}>
                          👤 Demote
                        </button>
                      )}
                      <button onClick={() => removeParticipant(p.userId)}>
                        🚫 Remove
                      </button>
                    </div>
                  )}
                </li>
              ))}
            </ul>
          </div>

          <div className="chat-section">
            <h3>💬 Live Chat</h3>
            <div className="chat-messages">
              {chatMessages.map((msg, idx) => (
                <div key={idx} className={`chat-message ${msg.sender === 'system' ? 'system' : ''}`}>
                  <strong>{msg.sender === 'system' ? '📢' : msg.sender}:</strong> {msg.message}
                </div>
              ))}
              {chatMessages.length === 0 && (
                <div style={{ textAlign: 'center', color: '#999', padding: '20px' }}>
                  💬 No messages yet. Start the conversation!
                </div>
              )}
            </div>
            <div className="chat-input">
              <input
                type="text"
                placeholder="Type your message..."
                value={chatInput}
                onChange={(e) => setChatInput(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && sendChat()}
              />
              <button onClick={sendChat}>📤 Send</button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Room;
